import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";

const UserDashboard = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchLogs();
    const interval = setInterval(fetchLogs, 3000); // Live refresh
    return () => clearInterval(interval);
  }, []);

  async function fetchLogs() {
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("time", { ascending: false }) // Newest first
      .limit(20);

    if (error) console.log("Error:", error);
    else setLogs(data || []);
    setLoading(false);
  }

  // Stats Logic
  const latestPlate = logs.length > 0 ? logs[0].plate : "--";
  const todayCount = logs.filter(l => new Date(l.time).toDateString() === new Date().toDateString()).length;
  
  // Filter Logic
  const filteredLogs = logs.filter(log => 
    log.plate.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <main className="dashboard-root">
      
      {/* 1. TOP STATS */}
      <section className="summary-row">
        <div className="summary-card blue">
          <div className="summary-title">🚘 Latest Entry</div>
          <div className="summary-num" style={{fontFamily: "monospace", color: "#007bff"}}>{latestPlate}</div>
        </div>

        <div className="summary-card green">
          <div className="summary-title">📅 Vehicles Today</div>
          <div className="summary-num">{todayCount}</div>
        </div>

        <div className="summary-card">
          <div className="summary-title">📡 System Status</div>
          <div className="summary-num" style={{fontSize: "24px", color: "green"}}>Online</div>
        </div>
      </section>

      {/* 2. SEARCH BAR */}
      <div className="controls" style={{justifyContent: "space-between"}}>
        <h2 className="layout-title">📋 Live Entry Feed</h2>
        <input 
          className="search" 
          placeholder="🔍 Search Plate..." 
          value={searchTerm} 
          onChange={e => setSearchTerm(e.target.value)} 
        />
      </div>

      {/* 3. LIST TABLE (Replaces Slot Grid) */}
      <section className="table-card">
        <table className="log-table">
          <thead>
            <tr>
              <th>Time</th>
              <th>License Plate</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {loading ? <tr><td colSpan="3" style={{textAlign:"center", padding:"20px"}}>Loading...</td></tr> : 
            filteredLogs.map(log => (
              <tr key={log.id}>
                <td>{new Date(log.created_at).toLocaleString()}</td>
                <td style={{fontWeight: "bold", fontFamily: "monospace", fontSize: "1.1em"}}>{log.plate}</td>
                <td><span className="badge-enter">Entered</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <footer className="small-footer">Updated: {new Date().toLocaleTimeString()}</footer>
    </main>
  );
};

export default UserDashboard;
